const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Aleppo, Syria location
  const aleppo = ee.Geometry.Point([37.16, 36.2]);
  const region = aleppo.buffer(5000); // 5km buffer around city center

  // Define time periods
  const start2012 = '2012-04-01';
  const end2012 = '2012-12-31';
  const start2016 = '2016-01-01';
  const end2016 = '2016-12-31';

  // Load VIIRS nighttime lights
  const viirs2012 = ee.ImageCollection('NOAA/VIIRS/DNB/MONTHLY_V1/VCMSLCFG')
    .filterBounds(region)
    .filterDate(start2012, end2012)
    .select('avg_rad');

  const viirs2016 = ee.ImageCollection('NOAA/VIIRS/DNB/MONTHLY_V1/VCMSLCFG')
    .filterBounds(region)
    .filterDate(start2016, end2016)
    .select('avg_rad');

  // Check collection sizes
  const size2012 = await viirs2012.size().getInfo();
  const size2016 = await viirs2016.size().getInfo();

  console.log(`2012 Images: ${size2012}`);
  console.log(`2016 Images: ${size2016}`);

  if (size2012 === 0 || size2016 === 0) {
    console.log('<answer>C1</answer>');
    return;
  }

  // Calculate mean composites
  const mean2012 = viirs2012.mean();
  const mean2016 = viirs2016.mean();

  // Calculate statistics
  const stats2012 = await mean2012.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const stats2016 = await mean2016.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const val2012 = stats2012.avg_rad_mean;
  const count2012 = stats2012.avg_rad_count;
  const val2016 = stats2016.avg_rad_mean;
  const count2016 = stats2016.avg_rad_count;

  console.log(`2012: Mean=${val2012}, Pixels=${count2012}`);
  console.log(`2016: Mean=${val2016}, Pixels=${count2016}`);

  // Check for invalid pixels
  if (count2012 === 0 || count2016 === 0) {
    console.log('<answer>C2</answer>');
    return;
  }

  // Check for invalid values
  if (val2012 === null || val2016 === null || 
      val2012 === undefined || val2016 === undefined ||
      isNaN(val2012) || isNaN(val2016)) {
    console.log('<answer>C3</answer>');
    return;
  }

  // Calculate change
  const change = val2016 - val2012;
  const pctChange = ((val2016 - val2012) / val2012) * 100;

  console.log(`Change: ${change.toFixed(4)} (${pctChange.toFixed(1)}%)`);

  // Determine answer: decrease means 2016 < 2012
  if (val2016 < val2012) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
